function describe(node, depth) {
  const out = { id: node.id, name: node.name, type: node.type, w: Math.round(node.width), h: Math.round(node.height) };
  if ('fills' in node && Array.isArray(node.fills)) out.fills = JSON.stringify(node.fills).slice(0, 400);
  if ('cornerRadius' in node && typeof node.cornerRadius === 'number') out.radius = node.cornerRadius;
  if ('strokes' in node && Array.isArray(node.strokes) && node.strokes.length) { out.strokes = JSON.stringify(node.strokes).slice(0,300); out.strokeWeight = node.strokeWeight; }
  if (node.type === 'TEXT') {
    out.characters = node.characters;
    try { out.font = node.fontName ? JSON.stringify(node.fontName) : 'mixed'; } catch(e) { out.font = 'mixed'; }
    out.fontSize = node.fontSize;
  }
  if (depth > 0 && 'children' in node) out.children = node.children.map(c => describe(c, depth - 1));
  return out;
}
