const f09 = await figma.getNodeByIdAsync('2022:689');
function byName(parent,name){ return parent.children.find(c=>c.name===name); }
const sw = byName(f09,'View / Income-Expenses'); sw.y = 164;
const per = byName(f09,'Period / Monthly'); per.y = 220;
const dc = byName(f09,'Income Breakdown'); dc.y = 260; dc.resize(327,244);
const cyShift = 96; // chart center y within dc; adjust arcs & center texts
const cx=163.5, d=140, cy=88;
for(const c of dc.children){
  if(c.type==='ELLIPSE' && c.name.startsWith('Arc /')){ c.y = cy - d/2; }
}
const hl = dc.children.find(c=>c.type==='TEXT'&&c.characters==='52%'); if(hl) hl.y = cy - hl.height/2 - 4;
const hs = dc.children.find(c=>c.type==='TEXT'&&c.characters==='Sales'); if(hs) hs.y = cy + 14;
for(const c of dc.children){
  if(c.type==='TEXT' && ['Sales','Investment','Other','$15,190.00','$11,451.03','$2,590.00','39%','9%'].includes(c.characters) && c.y>150){ c.y -= 12; }
  if(c.type==='ELLIPSE' && !c.name.startsWith('Arc')){ c.y -= 12; }
}
// legend rows: recompute clean
let rowIdx=0;
const legendNames=['Sales','Investment','Other'];
for(const c of dc.children){
  if(c.type==='TEXT' && legendNames.includes(c.characters) && c.x>10){ /* name cells */ }
}
// Simpler: reposition legend block: find the three name texts at x==40
const nameTs = dc.children.filter(c=>c.type==='TEXT' && legendNames.includes(c.characters) && Math.round(c.x)===40);
const valTs = dc.children.filter(c=>c.type==='TEXT' && c.characters.startsWith('$') && c.x>=170);
const pctTs = dc.children.filter(c=>c.type==='TEXT' && ['39%','9%'].includes(c.characters));
const dotTs = dc.children.filter(c=>c.type==='ELLIPSE' && !c.name.startsWith('Arc'));
const ys = [176, 196, 216];
nameTs.forEach((t,i)=>{ t.y = ys[i]; });
valTs.forEach((t,i)=>{ t.y = ys[i]; });
pctTs.forEach((t,i)=>{ t.y = ys[i+1]; });
dotTs.forEach((t,i)=>{ t.y = ys[i]+3; });
// Totals card
const tot = byName(f09,'Totals'); tot.y = 520;
const tabBar = f09.children.find(c=>c.name && c.name.startsWith('Nav / Tab Bar')); if(tabBar) tabBar.y = 714;
return 'fixed 09';

